import random
class DB:
    def __init__(self):
        self.kv = {f"k{i}": i for i in range(20)}
        self.expire = {f"k{i}": (i < 8) for i in range(20)}  # 前 8 个已过期
        self.active_deleted = 0
    def active_expire(self, sample=10):
        keys = random.sample(list(self.kv.keys()), sample)
        for k in keys:
            if self.expire.get(k):
                del self.kv[k]; del self.expire[k]; self.active_deleted += 1
        return len(keys)

random.seed(0)
db = DB()
print("定期删除(active/expire):")
before = len(db.kv)
db.active_expire(10)
print("  采样 10 个 key, 删除过期:", db.active_deleted, "个")
print("  删除前 key 数:", before, " 删除后:", len(db.kv))
print("  特点: 每秒多次, 每次抽少量样本, 平衡 CPU 与内存回收(非全量扫描)")
